// Translations of the DETAILED-mode quiz (the 50 deeper probes in
// lib/quiz-questions-detailed.ts). Keyed by question index → locale →
// { p, a:[{t}] }, mirroring the structure the content-translation
// pipeline emits for array sub-fields.
//
// This is the detailed-mode companion to QUICK_QUIZ_I18N in
// lib/quiz-i18n.ts. The quick set was hand-extracted from mull.html;
// this one is GENERATED by scripts/translate-content.mjs into the
// region between the BEGIN/END sentinels. Don't hand-edit inside them —
// re-running the script rewrites the whole block. The type + the
// getLocalizedDetailedQuestion helper below are hand-maintained.
//
// English is the source (lives in DETAILED_QUESTIONS itself), so it's
// never stored here; a missing locale/field falls back to English at
// the call site (app/quiz/quiz-engine.tsx).

import type { Locale } from './translations';

export type DetailedQuestionI18nFields = {
  /** Translated prompt. */
  p?: string;
  /** Translated answers, in DETAILED_QUESTIONS[idx].a order. The pipeline
   *  emits array sub-fields as objects ({ t }), so each entry is { t }. */
  a?: Array<{ t?: string }>;
};

/** Normalized view handed to the quiz engine: prompt + a flat array of
 *  answer strings (undefined where a particular answer wasn't translated,
 *  so the caller falls back to the English source for just that slot). */
export type LocalizedQuestionView = {
  p?: string;
  a: Array<string | undefined>;
};

