/** Look up a translated detailed-mode question, normalized to a flat
 *  answer-string array. Returns undefined when the index has no entry for
 *  the locale (caller falls back to English in DETAILED_QUESTIONS). */
export function getLocalizedDetailedQuestion(
  idx: number,
  locale: Locale,
): LocalizedQuestionView | undefined {
  const o = DETAILED_QUIZ_I18N[String(idx)]?.[locale];
  if (!o) return undefined;
  return {
    p: o.p,
    a: (o.a ?? []).map((x) => x?.t),
  };
}
